import { useState } from 'react';
import { Card } from '@/components/ui/Card';
import { Button } from '@/components/ui/Button';

/**
 * The comparison API contract has not yet been confirmed by the backend team.
 * Keep the entry point in the results workflow without fabricating API data.
 */
export function ModelCostComparison() {
  const [expanded, setExpanded] = useState(false);

  return (
    <Card title="Compare Across LLMs">
      <p className="mb-4 text-sm text-slate-600 dark:text-slate-300">
        See how your original and optimized prompts compare in cost across different AI models.
      </p>
      <Button
        aria-expanded={expanded}
        aria-controls="model-cost-comparison-details"
        onClick={() => setExpanded((value) => !value)}
      >
        {expanded ? 'Hide comparison' : 'Compare All Supported LLMs'}
      </Button>
      {expanded && (
        <div id="model-cost-comparison-details" className="mt-4 rounded-md border border-black/10 bg-surface/30 p-4 text-sm dark:border-white/10">
          <p className="font-medium">Model comparison is not available yet.</p>
          <p className="mt-1 text-slate-600 dark:text-slate-300">
            TokenTrim needs the confirmed comparison API contract from the backend before it can request or display model estimates.
          </p>
        </div>
      )}
    </Card>
  );
}
